// === pubspec.yaml (фрагмент, п. 1 ТЗ) ===
dependencies:
  flutter:
    sdk: flutter
  shared_preferences: ^2.5.6  // локальне збереження даних

// === lib/models/user_data.dart ===
/// Модель даних користувача, які зберігаються локально у SharedPreferences
/// (п. 3 ТЗ ЛР 10: ім'я, email, пароль)
class UserData {
  /// Ім'я користувача
  final String name;

  /// Email користувача
  final String email;

  /// Пароль (поле, передбачене формою реєстрації)
  final String password;

  const UserData({
    required this.name,
    required this.email,
    required this.password,
  });

  @override
  String toString() => 'UserData(name: $name, email: $email)';
}

// === lib/services/user_storage_service.dart (п. 1-4, 6-8 ТЗ) ===
import 'package:shared_preferences/shared_preferences.dart';

import '../models/user_data.dart';

/// Сервіс локального збереження даних через SharedPreferences (п. 1 ТЗ ЛР 10):
/// - дані користувача з екрана реєстрації (ім'я, email, пароль) — п. 2, 3 ТЗ;
/// - список ідентифікаторів обраних елементів (favorites ids) — п. 6, 7 ТЗ.
class UserStorageService {
  // Ключі збереження даних користувача (п. 3 ТЗ)
  static const String keyName = 'user_name';
  static const String keyEmail = 'user_email';
  static const String keyPassword = 'user_password';
  static const String keyIsRegistered = 'is_registered';

  // Ключ списку favorites ids (п. 7 ТЗ)
  static const String keyFavoriteIds = 'favorite_ids';

  /// Збереження даних користувача, введених на екрані реєстрації (п. 2, 3 ТЗ)
  Future<void> saveUser({
    required String name,
    required String email,
    required String password,
  }) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(keyName, name);
    await prefs.setString(keyEmail, email);
    await prefs.setString(keyPassword, password);
    await prefs.setBool(keyIsRegistered, true);
  }

  /// Завантаження даних користувача після повторного запуску (п. 4 ТЗ).
  /// Повертає null, якщо користувач ще не реєструвався.
  Future<UserData?> loadUser() async {
    final prefs = await SharedPreferences.getInstance();
    if (prefs.getBool(keyIsRegistered) ?? false) {
      return UserData(
        name: prefs.getString(keyName) ?? '',
        email: prefs.getString(keyEmail) ?? '',
        password: prefs.getString(keyPassword) ?? '',
      );
    }
    return null;
  }

  /// Прапорець наявності збереженого користувача (п. 4 ТЗ)
  Future<bool> isRegistered() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getBool(keyIsRegistered) ?? false;
  }

  /// Отримання збережених favorites ids (п. 8 ТЗ)
  Future<List<String>> loadFavoriteIds() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getStringList(keyFavoriteIds) ?? const [];
  }

  /// Збереження списку favorites ids (п. 6, 7 ТЗ)
  Future<void> saveFavoriteIds(List<String> favoriteIds) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setStringList(keyFavoriteIds, favoriteIds);
  }

  /// Видалення даних користувача (вихід з облікового запису)
  Future<void> clearUser() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove(keyName);
    await prefs.remove(keyEmail);
    await prefs.remove(keyPassword);
    await prefs.remove(keyIsRegistered);
  }

  /// Видалення збережених favorites ids
  Future<void> clearFavorites() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove(keyFavoriteIds);
  }

  /// Повне очищення локального сховища (вихід + скидання обраного)
  Future<void> clearAll() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.clear();
  }
}

// === lib/screens/welcome_screen.dart (фрагмент, п. 4 ТЗ) ===
class _WelcomeScreenState extends State<WelcomeScreen> {
  final UserStorageService _userStorage = UserStorageService();

  @override
  void initState() {
    super.initState();
    _restoreSession();
  }

  // Якщо дані користувача вже збережені — сесія відновлюється
  // і застосунок одразу переходить у менеджер завдань (п. 4 ТЗ ЛР 10)
  Future<void> _restoreSession() async {
    final user = await _userStorage.loadUser();
    if (user != null && mounted) {
      Navigator.of(context).pushReplacement(
        MaterialPageRoute(
          builder: (context) => TaskManagerScreen(
            username: user.name,
            email: user.email,
            password: user.password,
            onToggleTheme: widget.onToggleTheme,
          ),
        ),
      );
    }
  }
}

// === lib/screens/register_screen.dart (фрагмент, п. 2-3 ТЗ) ===
  // П. 2, 3 ТЗ ЛР 10: дані користувача зберігаються у SharedPreferences
  Future<void> _submitForm() async {
    if (_formKey.currentState!.validate()) {
      final String username = _usernameController.text.trim();
      final String email = _emailController.text.trim();
      final String password = _passwordController.text;

      // Локальне збереження даних користувача (ім'я, email, пароль)
      await UserStorageService().saveUser(
        name: username,
        email: email,
        password: password,
      );
      if (!mounted) return;

      // Навігація на TaskManagerScreen із передачею даних користувача
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (context) => TaskManagerScreen(
            username: username,
            email: email,
            password: password,
            onToggleTheme: widget.onToggleTheme,
          ),
        ),
      );
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Будь ласка, заповніть усі поля форми!')),
      );
    }
  }

// === lib/screens/login_screen.dart (фрагмент, п. 4 ТЗ) ===
  // П. 4 ТЗ ЛР 10: якщо користувач збережено у SharedPreferences, дані
  // входу звіряються зі збереженими та сесія відновлюється.
  Future<void> _submitLogin() async {
    if (_formKey.currentState!.validate()) {
      final String email = _emailController.text.trim();
      final String password = _passwordController.text;

      // Завантаження збереженого користувача з локального сховища
      final UserData? saved = await UserStorageService().loadUser();
      if (!mounted) return;

      // Ім'я користувача: зі збережених даних або з локальної частини email
      String username;
      if (saved != null) {
        if (saved.email != email || saved.password != password) {
          _showError('Невірний email або пароль');
          return;
        }
        username = saved.name;
      } else {
        username = email.split('@').first;
      }

      // Навігація на TaskManagerScreen із відновленими даними користувача
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (context) => TaskManagerScreen(
            username: username,
            email: email,
            password: password,
            onToggleTheme: widget.onToggleTheme,
          ),
        ),
      );
    }
  }

// === lib/screens/task_manager_screen.dart (фрагменти, п. 6-9 ТЗ) ===
  // 1. Зчитування даних із JSON-файлу та відновлення favorites ids
  //    із SharedPreferences (п. 8, 9 ТЗ ЛР 10)
  Future<void> _loadTasksFromJson() async {
    final loadedTasks = await _storageService.loadTasks();
    // Відновлення обраних елементів за збереженими id
    final savedIds = await _userStorage.loadFavoriteIds();
    for (final task in loadedTasks) {
      task.isFavorite = savedIds.contains(task.id.toString());
    }
    setState(() {
      _tasks = loadedTasks;
      _favoriteIds = savedIds;
      _isLoading = false;
    });
  }

  // 3. Синхронізація favorites ids у SharedPreferences (п. 6, 7 ТЗ ЛР 10)
  //    — зберігається лише список ідентифікаторів обраних елементів
  Future<void> _persistFavoriteIds() async {
    final ids =
        _tasks.where((t) => t.isFavorite).map((t) => t.id.toString()).toList();
    _favoriteIds = ids;
    await _userStorage.saveFavoriteIds(ids);
  }

  // 4. Додавання/видалення елемента зі списку обраного (п. 6 ТЗ)
  void _toggleFavorite(TaskModel task) {
    setState(() {
      task.isFavorite = !task.isFavorite;
    });
    _persistTasks();
    _persistFavoriteIds();
    _showSnackBar(
      task.isFavorite
          ? 'Додано до обраного ❤️ (id збережено в SharedPreferences)'
          : 'Видалено з обраного 🤍 (id видалено з SharedPreferences)',
    );
  }

  // Фільтр «Обрані» (п. 9 ТЗ ЛР 10): лише ті елементи,
  // id яких містяться у списку збережених
  List<TaskModel> get _filteredTasks {
    switch (_currentFilter) {
      case TaskFilter.favorites:
        return _tasks
            .where((t) => _favoriteIds.contains(t.id.toString()))
            .toList();
      case TaskFilter.all:
      default:
        return _tasks;
    }
  }

// === lib/screens/profile_screen.dart (фрагмент, п. 5 ТЗ) ===
  /// Картка з даними користувача, збереженими у SharedPreferences (п. 4, 5 ТЗ ЛР 10)
  Widget _buildSavedDataCard(BuildContext context, bool isDark) {
    final bool hasSaved = _savedUser != null;
