        borderRadius: BorderRadius.circular(14),
        side: BorderSide(color: AppColors.divider(isDark)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Заголовок картки
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 4),
            child: Row(
              children: [
                Icon(
                  Icons.save_alt_outlined,
                  size: 20,
                  color: AppColors.secondary,
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    'Дані зі сховища (SharedPreferences)',
                    style: TextStyle(
                      fontWeight: FontWeight.w600,
                      fontSize: 14,
                      color: isDark ? AppColors.textDark : AppColors.textLight,
                    ),
                  ),
                ),
              ],
            ),
          ),
          if (!hasSaved)
            const Padding(
              padding: EdgeInsets.fromLTRB(16, 4, 16, 14),
              child: Text('Збережених даних немає'),
            )
          else ...[
            _buildSavedRow(context, isDark,
                icon: Icons.person_outline, label: 'Ім'я', value: _displayName),
            _buildSavedRow(context, isDark,
                icon: Icons.alternate_email, label: 'Email', value: _displayEmail),
            // Пароль приховано крапочками, показ/сховати — за іконку
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: Row(
                children: [
                  Icon(
                    Icons.lock_outline,
                    size: 18,
                    color: AppColors.textSecondary(isDark),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      _showPassword
                          ? _displayPassword
                          : '•' * _displayPassword.length,
                      style: const TextStyle(fontWeight: FontWeight.w600),
                    ),
                  ),
                ],
              ),
            ),
          ],
        ],
      ),
    );
  }

